contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        uint64 _sequenceNumber2
    ) public {
        // Step 1: depositor call succeeds and sets sequenceNumber.
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        uint64 afterDepositor = c.sequenceNumber();

        // Step 2: a non-depositor call must revert and not change sequenceNumber.
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber2,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );

        bool reverted = !ok;
        uint64 afterNonDepositor = c.sequenceNumber();

        // General rule: the depositor's value is stored, the non-depositor attempt reverts,
        // and the non-depositor attempt leaves sequenceNumber exactly as the depositor set it.
        assert(
            afterDepositor == _sequenceNumber &&
            reverted &&
            afterNonDepositor == _sequenceNumber
        );
    }
}

